package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.factorialDouble
 */
public class MathUtils_factorialDouble_TriageGen1Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testFactorialDouble_WithZero() {
        // 0! = 1
        double expected = 1.0;
        double actual = MathUtils.factorialDouble(0);
        assertEquals("factorialDouble(0) should be 1.0", expected, actual, DELTA);
    }

    @Test
    public void testFactorialDouble_WithSmallPositiveInteger() {
        // 5! = 120
        double expected = 120.0;
        double actual = MathUtils.factorialDouble(5);
        assertEquals("factorialDouble(5) should be 120.0", expected, actual, DELTA);
    }

    @Test
    public void testFactorialDouble_WithLargerInteger() {
        // 10! = 3628800
        double expected = 3628800.0;
        double actual = MathUtils.factorialDouble(10);
        assertEquals("factorialDouble(10) should be 3628800.0", expected, actual, DELTA);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testFactorialDouble_WithNegativeInteger_ThrowsException() {
        // n < 0 should throw IllegalArgumentException
        MathUtils.factorialDouble(-1);
    }

    @Test
    public void testFactorialDouble_WithLargeN() {
        // Testing a larger value to ensure precision/scale handling via log/exp
        // 20! is approx 2.432902e18
        double expected = 2432902008176640000.0; 
        double actual = MathUtils.factorialDouble(20);
        // Using a larger delta for very large doubles due to precision limits of double
        assertEquals("factorialDouble(20) should match 20!", expected, actual, 1e6);
    }
}
